steps.script:
var ov = tree.root.get_node("/root/TutorialOverlay")
var wt = tree.root.get_node_or_null("/root/Main/HUD_Right/VBoxContainer/ShootingScrollContainer/ShootingPanel/DeclarationBox/WeaponTree")
if wt == null:
	return "no weapon tree"
if not ov._anchor_ok:
	return "anchor never resolved"
if not ov._anchor_rect.is_equal_approx(wt.get_global_rect()):
	return "spotlight is not on the weapon tree: %s vs %s" % [str(ov._anchor_rect), str(wt.get_global_rect())]
var panel: Rect2 = tree.root.get_node("/root/Main/HUD_Right").get_global_rect()
if ov._anchor_rect.size.x < panel.size.x - 20.0:
	return "weapon tree no longer fills the panel (%s in %s) — the clamp assertions below would prove nothing" % [str(ov._anchor_rect), str(panel)]
return "ok"

var atc = tree.root.get_node_or_null("/root/Main/HUD_Right/VBoxContainer/ShootingScrollContainer/ShootingPanel/DeclarationBox/AutoTargetContainer")
if atc == null or not atc.visible:
	return "the 'Same target for all' row is not showing — this scenario would not be exercising the widest state of the panel"
return "ok"

var sc = tree.root.get_node_or_null("/root/Main/HUD_Right/VBoxContainer/ShootingScrollContainer")
if sc == null:
	return "no ShootingScrollContainer"
var p = sc.get_node_or_null("ShootingPanel")
if p == null:
	return "no ShootingPanel"
var bad: Array = []
# The panel's content must start at the scroll viewport's left edge. Any
# horizontal scroll offset clips the FIRST n px off every row — weapon names,
# section headers, unit rows — which is exactly the reported symptom.
if absf(p.get_global_rect().position.x - sc.get_global_rect().position.x) > 1.0:
	bad.append("panel starts at %.0f but the viewport starts at %.0f (%.0fpx clipped off the left)" % [p.get_global_rect().position.x, sc.get_global_rect().position.x, sc.get_global_rect().position.x - p.get_global_rect().position.x])
if sc.scroll_horizontal != 0:
	bad.append("scroll_horizontal is %d, not 0" % sc.scroll_horizontal)
if sc.get_h_scroll_bar().visible:
	bad.append("a horizontal scrollbar appeared — the panel content is wider than HUD_Right")
if p.get_combined_minimum_size().x > sc.get_global_rect().size.x + 0.5:
	bad.append("panel needs %.0fpx but the viewport is %.0fpx" % [p.get_combined_minimum_size().x, sc.get_global_rect().size.x])
return "ok" if bad.is_empty() else "; ".join(bad)

